#!/usr/bin/env bash
# Waybar Caps/Num lock badge (reads keyboard LEDs)  (generated by theme.py)
c=$(cat /sys/class/leds/*::capslock/brightness 2>/dev/null | sort -r | head -1)
n=$(cat /sys/class/leds/*::numlock/brightness 2>/dev/null | sort -r | head -1)
# Num Lock is normally on (numpad) so only Caps Lock earns a badge; both are in the tooltip.
t=""; cls=none; [ "$c" = 1 ] && t="󰪛 Caps Lock" && cls=caps
printf '{"text":"%s","class":"%s","tooltip":"Caps Lock: %s · Num Lock: %s"}\n' "$t" "$cls" "$([ "$c" = 1 ] && echo on || echo off)" "$([ "$n" = 1 ] && echo on || echo off)"
